\section{Introduction}

\subsection{The diagonal engine}
A remarkable number of limitative theorems are one argument in different
clothes. Cantor's theorem, Russell's paradox, the undecidability of the halting
problem, Tarski's undefinability of truth, and G\"odel's first incompleteness
theorem all reduce to Lawvere's statement that a point-surjective map forces
every endomorphism of the codomain to have a fixed point; contrapositively, a
fixed-point-free endomorphism destroys point-surjectivity.

At set level: let $A$ be a set of \emph{codes}, $B$ a set of \emph{meanings},
and $\ev : A \to (A \to B)$ an evaluation, written $\ev(a,x)$. The
\emph{diagonal} is $x \mapsto \ev(x,x)$. If $\ev$ is surjective onto $A \to B$
then for any $f : B \to B$ the observation $x \mapsto f(\ev(x,x))$ has a code
$c$, and instantiating at $c$ yields $\ev(c,c) = f(\ev(c,c))$.

\subsection{The comparative programme}
This invites a comparative programme: build formal, visual and contrapuntal
syntaxes of self-reference, each with a universal table, link them by
evaluation-preserving equivalences, and observe that their diagonal witnesses
agree. The guiding intuition, that preservation of the \emph{binary} evaluation
table rather than a bare bijection of artifacts is what makes fixed points
transport, is exactly right. The programme nevertheless cannot be run with
universality, for the reason given in Section~\ref{sec:vacuity}.

\subsection{Contributions}
Section~\ref{sec:vacuity} proves vacuity of universality and sharpness of the
dichotomy. Section~\ref{sec:graded} introduces graded universality and proves
the Obstruction Spectrum Theorem. Section~\ref{sec:pointwise} refutes monoid
control and separates richness from diagonal closure.
Section~\ref{sec:choice} treats choice dependence and canonicity.
Section~\ref{sec:simulations} establishes the four-level coherence hierarchy.
Section~\ref{sec:triad} constructs an explicit graded triad over pitch classes.
Section~\ref{sec:counting} counts the spectrum and computes its density.

\section{Universality is vacuous}\label{sec:vacuity}

\begin{definition}[Presentation]
Let $A$ and $B$ be sets. A \emph{presentation} of $B$ over $A$ is a map
$\ev : A \to (A \to B)$ that is surjective: for every $g : A \to B$ there is
$c \in A$ with $\ev(c,x) = g(x)$ for all $x$.
\end{definition}

\begin{definition}
For distinct $b_1, b_2 \in B$ set
\[
  \swap_{b_1,b_2}(x) = \begin{cases} b_2, & x = b_1,\\ b_1, & x \neq b_1.
  \end{cases}
\]
\end{definition}

\begin{lemma}\label{lem:swap}
If $b_1 \neq b_2$ then $\swap_{b_1,b_2}$ has no fixed point.
\end{lemma}

\begin{proof}
If $x = b_1$ then $\swap(x) = b_2 \neq b_1 = x$; if $x \neq b_1$ then
$\swap(x) = b_1 \neq x$.
\end{proof}

The force of Lemma~\ref{lem:swap} is its uniformity: no algebraic structure on
$B$ is used, only the existence of two distinct points and classical case
analysis.

\begin{theorem}[Vacuity of universality]\label{thm:vacuity}
If a presentation $\ev : A \to (A \to B)$ exists, then $B$ is a subsingleton.
\end{theorem}

\begin{proof}
Let $b_1, b_2 \in B$ and suppose $b_1 \neq b_2$. Surjectivity applied to
$g(x) = \swap_{b_1,b_2}(\ev(x,x))$ yields a code $c$ with
$\ev(c,x) = \swap_{b_1,b_2}(\ev(x,x))$ for all $x$; instantiating at $x = c$
gives $\swap_{b_1,b_2}(\ev(c,c)) = \ev(c,c)$, contradicting
Lemma~\ref{lem:swap}.
\end{proof}

\begin{corollary}
If $B$ has two distinct elements then no presentation of $B$ exists over any
code set. In particular there is no presentation of the two-element domain of
truth values.
\end{corollary}

Thus the familiar Boolean obstruction, usually attributed to negation, is the
two-element instance of a general phenomenon: negation is precisely
$\swap_{\top,\bot}$.

\begin{proposition}[Sharpness]
If $B$ is a subsingleton and $A$, $B$ are inhabited then a presentation of $B$
over $A$ exists, namely the constant table.
\end{proposition}

\begin{remark}
The dichotomy is exact at the boundary between one meaning and two, and the
obstruction is not cardinality (a Cantorian reading) but definability of a
fixed-point-free endomorphism. Any theorem hypothesising a universal
presentation over nontrivial semantics is a theorem about the empty set.
\end{remark}

\section{Graded universality and the obstruction spectrum}\label{sec:graded}

\begin{definition}
Let $\ev : A \times A \to B$ be an arbitrary table. It \emph{represents}
$g : A \to B$ if there is $c \in A$ with $\ev(c,x) = g(x)$ for all $x$. For
$f : B \to B$ it \emph{diagonally represents} $f$ if it represents the diagonal
composite $x \mapsto f(\ev(x,x))$, i.e.\ if there is $c$ with
\[
  \ev(c,x) = f(\ev(x,x)) \qquad \text{for all } x \in A;
\]
such a $c$ is a \emph{diagonal code for $f$}.
\end{definition}

\begin{theorem}[Graded Lawvere theorem]\label{thm:graded}
If $c$ is a diagonal code for $f$ in $\ev$, then $\ev(c,c)$ is a fixed point of
$f$. In particular $f$ has a fixed point.
\end{theorem}

\begin{proof}
Instantiate the defining equation at $x = c$.
\end{proof}

\begin{theorem}[Free graded model]\label{thm:free}
Let $F \subseteq B \to B$ be a family every member of which has a fixed point.
Then there exist $A$ and $\ev : A \times A \to B$ diagonally representing every
member of $F$ simultaneously.
\end{theorem}

\begin{proof}
Choose $b_f$ with $f(b_f) = b_f$ for each $f \in F$, and set $A = F \sqcup B$,
whose elements are \emph{labels} $\ell_f$ and \emph{literals} $\underline{b}$.
Define the self-value $d(\ell_f) = b_f$, $d(\underline b) = b$, and
\[
  \ev(\ell_f, x) = f(d(x)), \qquad \ev(\underline b, x) = b.
\]
Then $\ev(x,x) = d(x)$ for every code: for literals this is immediate, and for
labels $\ev(\ell_f,\ell_f) = f(b_f) = b_f = d(\ell_f)$ by the fixed-point
property. Hence $\ev(\ell_f,x) = f(d(x)) = f(\ev(x,x))$ for all $x$, so
$\ell_f$ is a diagonal code for $f$.
\end{proof}

\begin{theorem}[Obstruction Spectrum Theorem]\label{thm:spectrum}
For any set $B$ and any $F \subseteq B \to B$, there exists a single table
diagonally representing every $f \in F$ if and only if every $f \in F$ has a
fixed point.
\end{theorem}

\begin{proof}
Necessity is Theorem~\ref{thm:graded} applied memberwise; sufficiency is
Theorem~\ref{thm:free}.
\end{proof}

\begin{corollary}\label{cor:maximal}
The set $\Rep(B) = \{ f : B \to B \mid \exists b,\, f(b) = b\}$ is the greatest
jointly diagonally-representable family of endomorphisms of $B$, ordered by
inclusion.
\end{corollary}

Theorem~\ref{thm:spectrum} converts a question about syntax into a question
about semantics with no residue: no cardinality condition, no closure condition,
no structural condition on the code set.

\section{Representability is pointwise, not monoidal}\label{sec:pointwise}

\begin{theorem}[Failure of monoid control]\label{thm:monoid}
On $B = \{0,1,2\}$ let $t_A = (0\;1)$ and $t_B = (1\;2)$. A single table
diagonally represents both $t_A$ and $t_B$, while no table over any code set
diagonally represents $t_A \circ t_B$.
\end{theorem}

\begin{proof}
$t_A$ fixes $2$ and $t_B$ fixes $0$, so Theorem~\ref{thm:free} applies to
$F = \{t_A,t_B\}$. The composite sends $0 \mapsto 1 \mapsto 2 \mapsto 0$ and so
has no fixed point; Theorem~\ref{thm:graded} contraposed rules out any diagonal
code for it.
\end{proof}

\begin{remark}
The diagonal argument consumes $f$ exactly once, and the table of
Theorem~\ref{thm:free} never evaluates a composite; nothing forces closure. The
correct invariant is the pointwise fixed-point predicate on $F$, not any
algebraic invariant of the monoid $\langle F\rangle$. In particular $\Rep(B)$ is
not closed under composition.
\end{remark}

\begin{theorem}[Diagonal closure is a genuine extra axiom]
There is a table on the two-element domain of truth values representing every
constant observation, while no table over any code set diagonally represents
negation.
\end{theorem}

\begin{proof}
For the first claim take $\ev(a,x) = a$, so the code $b$ represents the constant
observation $b$. For the second, a diagonal code for negation would produce, by
Theorem~\ref{thm:graded}, a truth value $b$ with $\neg b = b$.
\end{proof}

\section{Choice dependence of the diagonal value}\label{sec:choice}

\begin{theorem}[Global code independence from semantic uniqueness]
\label{thm:codeindep}
Suppose $f : B \to B$ has at most one fixed point. Let $\evP$ and $\evQ$ be
arbitrary tables over arbitrary, unrelated code sets $A$ and $C$, with diagonal
codes $c \in A$ and $e \in C$ for $f$. Then $\evP(c,c) = \evQ(e,e)$.
\end{theorem}

\begin{proof}
Both values are fixed points of $f$ by Theorem~\ref{thm:graded}; uniqueness
identifies them.
\end{proof}

No relationship between the code sets is assumed. This separates the two
ambiguities in the construction: presentation ambiguity, which is canonical and
transports (Section~\ref{sec:simulations}), and code ambiguity, which is genuine
and collapses precisely under semantic uniqueness.

\begin{theorem}[Failure without uniqueness]
There is a table on the two-element domain of truth values in which every code
is a diagonal code for the identity and two codes have different diagonal
values.
\end{theorem}

\begin{proof}
Take the projection table $\ev(a,x) = x$. Then $\ev(c,x) = x = \ev(x,x)$ for
every $c$, so every code is a diagonal code for the identity, and the two codes
have diagonal values $\top$ and $\bot$.
\end{proof}

\begin{lemma}\label{lem:contraction}
If $f : \mathbb{R} \to \mathbb{R}$ satisfies $|f(x)-f(y)| \le K|x-y|$ with
$K < 1$, then $f$ has at most one fixed point.
\end{lemma}

\begin{proof}
If $f(b)=b$ and $f(b')=b'$ then $|b-b'| \le K|b-b'|$, so $(1-K)|b-b'| \le 0$ and
hence $|b-b'|=0$.
\end{proof}

\begin{theorem}[Canonical diagonal value for contractions]
For $f$ as in Lemma~\ref{lem:contraction}, all diagonal codes for $f$ in all
presentations, related or not, evaluate to one and the same real number.
\end{theorem}

\begin{proof}
Combine Lemma~\ref{lem:contraction} with Theorem~\ref{thm:codeindep}.
\end{proof}

By the Banach fixed-point theorem the common value is the limit of the iterates
$f^n(x_0)$ from any starting point, so the diagonal value of a contracting
semantics is canonical and computable, independent of the syntax expressing it.

\section{Weak simulations: a four-level hierarchy}\label{sec:simulations}

\begin{definition}
An \emph{evaluation-preserving equivalence} between $\evP : A \times A \to B$
and $\evQ : C \times C \to B$ is a bijection $\varphi : A \to C$ with
$\evQ(\varphi a, \varphi x) = \evP(a,x)$ for all $a,x$.
\end{definition}

\begin{theorem}[Transport]\label{thm:transport}
If $\varphi$ is an evaluation-preserving equivalence and $c$ is a diagonal code
for $f$ in $\evP$, then $\varphi(c)$ is a diagonal code for $f$ in $\evQ$ and
$\evQ(\varphi c, \varphi c) = \evP(c,c)$.
\end{theorem}

\begin{proof}
The value equality is preservation at $(c,c)$. For code-hood, given $y \in C$
write $y = \varphi x$ by surjectivity; then
$\evQ(\varphi c, \varphi x) = \evP(c,x) = f(\evP(x,x)) =
f(\evQ(\varphi x,\varphi x)) = f(\evQ(y,y))$.
\end{proof}

\begin{definition}
A \emph{coherent retraction} from $\evQ$ onto $\evP$ consists of $s : A \to C$
and $r : C \to A$ with $r\circ s = \id_A$ and the coherence law
$\evQ(c,x) = \evP(rc, rx)$ for all $c,x \in C$.
\end{definition}

\begin{theorem}[Retractions lift codes]
Under a coherent retraction, if $c$ is a diagonal code for $f$ in $\evP$ then
$s(c)$ is a diagonal code for $f$ in $\evQ$.
\end{theorem}

\begin{proof}
$\evQ(sc,y) = \evP(r(sc), ry) = \evP(c, ry) = f(\evP(ry,ry)) = f(\evQ(y,y))$,
using coherence, $r \circ s = \id$, the diagonal equation at $ry$, and coherence
again.
\end{proof}

\begin{definition}
An \emph{evaluation-preserving embedding} is an injection $\iota : A \to C$ with
$\evQ(\iota a, \iota x) = \evP(a,x)$ for all $a,x$.
\end{definition}

\begin{theorem}[Embeddings preserve values]
If $c$ is a diagonal code for $f$ in $\evP$ and $\iota$ is an
evaluation-preserving embedding, then $f(\evQ(\iota c,\iota c)) =
\evQ(\iota c, \iota c)$, and the diagonal equation holds on the image:
$\evQ(\iota c, \iota x) = f(\evQ(\iota x, \iota x))$ for all $x \in A$.
\end{theorem}

\begin{theorem}[Embeddings do not preserve code-hood]
There exist tables $\evP$ over a one-element code set and $\evQ$ over a
two-element code set, both valued in the truth values, an evaluation-preserving
embedding $\iota$, and a diagonal code $c$ for the identity in $\evP$, with
$\iota(c)$ not a diagonal code for the identity in $\evQ$.
\end{theorem}

\begin{proof}
Let $A = \{\ast\}$ with $\evP(\ast,\ast) = \top$, let $C = \{\top,\bot\}$ with
$\evQ(a,x) = a$, and $\iota(\ast) = \top$. Preservation holds, and $\ast$ is
trivially a diagonal code for the identity. But $\evQ(\top,\bot) = \top$ while
$\id(\evQ(\bot,\bot)) = \bot$.
\end{proof}

The failure mechanism is that the diagonal equation is universally quantified
over codes, and an embedding introduces new codes at which the transported code
may fail it. This is exactly why Theorem~\ref{thm:transport} needs surjectivity.

\begin{definition}
Let $\mathrm{rel} \subseteq A \times C$ and $R \subseteq B \times B$. Then
$\mathrm{rel}$ is a \emph{bisimulation observed through $R$} if
$\mathrm{rel}(a,c)$ implies $R(\evP(a,a), \evQ(c,c))$.
\end{definition}

\begin{theorem}[Bisimulation gives only observational agreement]
There are tables over one-element code sets valued in $\mathbb{N}$, bisimilar
for the parity relation, whose unique codes are diagonal codes for the identity
and whose diagonal values differ.
\end{theorem}

\begin{proof}
Take $\evP \equiv 0$ and $\evQ \equiv 2$ with the total relation on codes:
$0 \equiv 2 \pmod 2$, both codes are trivially diagonal codes for the identity,
and $0 \neq 2$.
\end{proof}

