\section{An explicit graded triad}\label{sec:triad}

Let $B = \mathbb{Z}/12\mathbb{Z}$ be the pitch classes, with
\[
  I(x) = -x, \qquad TI(x) = 6 - x, \qquad P(x) = x+1 .
\]
Then $I$ fixes $\{0,6\}$, $TI$ fixes $\{3,9\}$, and $P$ fixes nothing, since
$x+1 = x$ would give $1 = 0$ in $\mathbb{Z}/12\mathbb{Z}$.

Three syntaxes, each with two self-application operators and a family of
literals:
\begin{itemize}
  \item \emph{formal}: $\selfInvert$, $\selfTritone$, $\mathsf{lit}(b)$;
  \item \emph{visual}: $\mathsf{drawingHands}$, $\mathsf{mirrorHands}$,
        $\mathsf{frame}(b)$;
  \item \emph{contrapuntal}: $\mathsf{crab}$, $\mathsf{crabTritone}$,
        $\mathsf{note}(b)$.
\end{itemize}
Each carries the self-value $d$ given by $0$, $3$ and $b$ on the three
constructors, and the table
\[
  \ev(\text{first operator}, x) = I(d(x)), \quad
  \ev(\text{second operator}, x) = TI(d(x)), \quad
  \ev(\text{literal } b, x) = b .
\]

\begin{lemma}[Diagonal computes the self-value]\label{lem:selfval}
In each syntax, $\ev(x,x) = d(x)$ for all codes $x$.
\end{lemma}

\begin{proof}
Literals are immediate. For the first operator, $I(0) = 0$; for the second,
$TI(3) = 6-3 = 3$. The self-values were chosen to be fixed points, exactly as in
Theorem~\ref{thm:free}.
\end{proof}

\begin{lemma}
In each syntax, the first operator is a diagonal code for $I$ and the second a
diagonal code for $TI$.
\end{lemma}

\begin{proof}
The defining clauses give $I(d(x))$ and $TI(d(x))$; apply
Lemma~\ref{lem:selfval}.
\end{proof}

\begin{proposition}
The constructorwise correspondences $\selfInvert \leftrightarrow
\mathsf{drawingHands} \leftrightarrow \mathsf{crab}$, $\selfTritone
\leftrightarrow \mathsf{mirrorHands} \leftrightarrow \mathsf{crabTritone}$,
$\mathsf{lit} \leftrightarrow \mathsf{frame} \leftrightarrow \mathsf{note}$ are
evaluation-preserving equivalences.
\end{proposition}

\begin{theorem}[Common value across the triad]
The images of the formal inversion code under the two equivalences are diagonal
codes for $I$ in the visual and contrapuntal syntaxes; all three diagonal values
equal the pitch class $0$; and $I(0)=0$.
\end{theorem}

\begin{proof}
Transport is Theorem~\ref{thm:transport}; the values are $0$ by
Lemma~\ref{lem:selfval}.
\end{proof}

\begin{theorem}[Choice dependence, musically]
The same triad contains a second diagonal code, for $TI$, with diagonal value
$3 \neq 0$, and $TI(3) = 3$.
\end{theorem}

\begin{theorem}[Transposition is never representable]
No table over any code set diagonally represents $P(x) = x+1$.
\end{theorem}

\begin{proof}
A diagonal code would give $b$ with $b+1=b$, hence $1=0$ in
$\mathbb{Z}/12\mathbb{Z}$.
\end{proof}

Musically: a piece can be about its own inversion and remain coherent; it can
never be about its own transposition. The distinction is a fixed-point count.

\section{The size of the obstruction spectrum}\label{sec:counting}

\begin{lemma}\label{lem:fpf}
The number of fixed-point-free self-maps of an $n$-element set is $(n-1)^n$.
\end{lemma}

\begin{proof}
A self-map is an independent choice of image for each of the $n$ points, and
fixed-point-freeness constrains each coordinate to the $n-1$ values distinct
from that point; the constrained product has $\prod_b (n-1) = (n-1)^n$ elements.
\end{proof}

\begin{theorem}[Cardinality of the spectrum]
Over an $n$-element semantic domain exactly $n^n - (n-1)^n$ endomorphisms are
diagonally representable, and by Corollary~\ref{cor:maximal} this family is
maximal.
\end{theorem}

\begin{proof}
Representability equals possession of a fixed point
(Theorem~\ref{thm:spectrum}); subtract Lemma~\ref{lem:fpf} from $n^n$.
\end{proof}

