"""Algorithm 2: Construction of the Free Graded Self-Applicative Model.

Given a finite family F of endomorphisms of a finite domain B, each possessing
a fixed point, this constructs a SINGLE evaluation table that diagonally
represents every member of F simultaneously -- the constructive half of the
Obstruction Spectrum Theorem.

Codes are labels (one per member of F) plus literals (one per meaning).  The
self-value of a label is a chosen fixed point of its endomorphism, and of a
literal is the literal itself.  The table is

    ev(label_f, x) = f(selfval(x)),        ev(literal_b, x) = b .

The diagonal then reproduces the self-values, which is exactly what makes each
label a diagonal code.
"""

from __future__ import annotations

from typing import Dict, List, Optional, Sequence, Tuple

Code = Tuple[str, int]          # ("L", i) label of F[i]  |  ("b", b) literal b
Endo = Tuple[int, ...]


def first_fixed_point(f: Sequence[int]) -> Optional[int]:
    for b, fb in enumerate(f):
        if fb == b:
            return b
    return None


class FreeGradedModel:
    """The free table over a representable family, with verification."""

    def __init__(self, n: int, family: Sequence[Sequence[int]]) -> None:
        self.n: int = n
        self.family: List[Endo] = [tuple(f) for f in family]
        self.selfval: Dict[Code, int] = {}
        for i, f in enumerate(self.family):
            b = first_fixed_point(f)
            if b is None:
                raise ValueError(
                    f"member {i} = {tuple(f)} is fixed-point free, hence "
                    f"representable by no table at all")
            self.selfval[("L", i)] = b
        for b in range(n):
            self.selfval[("b", b)] = b
        self.codes: List[Code] = (
            [("L", i) for i in range(len(self.family))]
            + [("b", b) for b in range(n)]
        )

    def ev(self, a: Code, x: Code) -> int:
        """The self-application table."""
        kind, idx = a
        if kind == "L":
            return self.family[idx][self.selfval[x]]
        return idx

    def diagonal(self, x: Code) -> int:
        return self.ev(x, x)

    def diagonal_code(self, i: int) -> Code:
        """The diagonal code for the i-th member of the family."""
        return ("L", i)

    def diagonal_value(self, i: int) -> int:
        """ev(c, c) for the diagonal code c of member i: a fixed point."""
        c = self.diagonal_code(i)
        return self.ev(c, c)

    def verify(self) -> bool:
        """Check the diagonal law and every diagonal equation.

        Cost O((|F| + n) * (|F| + n)) evaluations.
        """
        if any(self.diagonal(x) != self.selfval[x] for x in self.codes):
            return False
        for i, f in enumerate(self.family):
            c = self.diagonal_code(i)
            if any(self.ev(c, x) != f[self.diagonal(x)] for x in self.codes):
                return False
            if f[self.diagonal_value(i)] != self.diagonal_value(i):
                return False
        return True


if __name__ == "__main__":
    model = FreeGradedModel(3, [(1, 0, 2), (0, 2, 1)])   # (0 1) and (1 2)
    print("codes:", model.codes)
    print("verified:", model.verify())
    for i in range(2):
        print(f"member {i}: diagonal code {model.diagonal_code(i)}, "
              f"diagonal value {model.diagonal_value(i)}")

"""Algorithm 3: Exhaustive Census of the Obstruction Spectrum.

Enumerates all n^n endomorphisms of an n-element domain of meanings, counts
those admitting a diagonal code (equivalently, those with a fixed point), and
checks the count against the closed form n^n - (n-1)^n.  It then tracks the
density towards its limit 1 - e^{-1}.

Brute force costs Theta(n^{n+1}) and is feasible to about n = 7; the closed
form is O(log n) arithmetic operations and is exact for every n.
"""

from __future__ import annotations

import itertools
import math
from typing import Dict, Iterator, List, Tuple

Endo = Tuple[int, ...]


def all_endomorphisms(n: int) -> Iterator[Endo]:
    """Every self-map of {0, ..., n-1}, as a value tuple."""
    return itertools.product(range(n), repeat=n)


def has_fixed_point(f: Endo) -> bool:
    return any(f[b] == b for b in range(len(f)))


def brute_force_count(n: int) -> int:
    """Number of representable endomorphisms, by exhaustive enumeration."""
    return sum(1 for f in all_endomorphisms(n) if has_fixed_point(f))


def closed_form_count(n: int) -> int:
    """n^n - (n-1)^n, the exact size of the maximal representable family."""
    return n ** n - (n - 1) ** n


def density(n: int) -> float:
    """1 - (1 - 1/n)^n, the representable share of an n-element domain."""
    return closed_form_count(n) / n ** n


def census(max_brute: int = 6, max_n: int = 12) -> List[Dict[str, object]]:
    """Tabulate the spectrum, validating the closed form where feasible."""
    rows: List[Dict[str, object]] = []
    for n in range(1, max_n + 1):
        cf = closed_form_count(n)
        bf = brute_force_count(n) if n <= max_brute else None
        if bf is not None and bf != cf:
            raise AssertionError(f"closed form disagrees with brute force at n={n}")
        rows.append({
            "n": n,
            "total": n ** n,
            "fixed_point_free": (n - 1) ** n,
            "representable": cf,
            "brute_force": bf,
            "density": density(n),
            "error_vs_limit": abs(density(n) - (1.0 - math.exp(-1.0))),
        })
    return rows


if __name__ == "__main__":
    for row in census():
        print(row)
    print("limit 1 - 1/e =", 1.0 - math.exp(-1.0))

"""Algorithm 4: Transport of Diagonal Codes Across Presentations.

Verifies that a bijection of code sets preserves the whole evaluation table in
BOTH arguments -- an evaluation-preserving equivalence -- and, when it does,
transports a diagonal code from one presentation to the other, checking that
the diagonal value is unchanged.

It also implements the three weaker levels of the coherence hierarchy, so that
one can see exactly what each preserves:

    equivalence          codes transport, values equal
    coherent retraction  codes lift upward, values equal
    embedding            values only (code-hood can fail)
    bisimulation         observations only (values can differ)

Verifying an equivalence costs O(|A|^2) evaluations; transporting a code and
re-verifying it costs O(|A|).
"""

from __future__ import annotations

from typing import Callable, Hashable, List, Sequence, Tuple, TypeVar

A = TypeVar("A", bound=Hashable)
C = TypeVar("C", bound=Hashable)
B = TypeVar("B", bound=Hashable)

Table = Callable[[Hashable, Hashable], Hashable]


def is_diagonal_code(codes: Sequence[Hashable], ev: Table,
                     f: Callable[[Hashable], Hashable],
                     c: Hashable) -> bool:
    """Check  ev(c, x) = f(ev(x, x))  for every code x."""
    return all(ev(c, x) == f(ev(x, x)) for x in codes)


def diagonal_value(ev: Table, c: Hashable) -> Hashable:
    """The value ev(c, c); a fixed point of f whenever c is a diagonal code."""
    return ev(c, c)


def is_evaluation_preserving(codes_src: Sequence[Hashable], ev_src: Table,
                             ev_dst: Table,
                             phi: Callable[[Hashable], Hashable]) -> bool:
    """Check  ev_dst(phi a, phi x) = ev_src(a, x)  for all a, x."""
    return all(ev_dst(phi(a), phi(x)) == ev_src(a, x)
               for a in codes_src for x in codes_src)


def transport_diagonal_code(codes_src: Sequence[Hashable], ev_src: Table,
                            codes_dst: Sequence[Hashable], ev_dst: Table,
                            phi: Callable[[Hashable], Hashable],
                            f: Callable[[Hashable], Hashable],
                            c: Hashable) -> Tuple[bool, Hashable, Hashable]:
    """Transport a diagonal code along an evaluation-preserving equivalence.

    Returns (success, image_code, common_diagonal_value).  Success requires
    that phi preserve evaluation, that phi be surjective onto the destination
    codes, that c be a diagonal code in the source, and that the image be a
    diagonal code in the destination with an equal diagonal value.
    """
    if not is_evaluation_preserving(codes_src, ev_src, ev_dst, phi):
        return (False, None, None)
    image = {phi(a) for a in codes_src}
    if image != set(codes_dst):
        return (False, None, None)          # not surjective: only an embedding
    if not is_diagonal_code(codes_src, ev_src, f, c):
        return (False, None, None)
    pc = phi(c)
    ok = (is_diagonal_code(codes_dst, ev_dst, f, pc)
          and diagonal_value(ev_dst, pc) == diagonal_value(ev_src, c))
    return (ok, pc, diagonal_value(ev_src, c))


def lift_along_retraction(codes_dst: Sequence[Hashable], ev_src: Table,
                          ev_dst: Table,
                          sect: Callable[[Hashable], Hashable],
                          retr: Callable[[Hashable], Hashable],
                          codes_src: Sequence[Hashable],
                          f: Callable[[Hashable], Hashable],
                          c: Hashable) -> bool:
    """Lift a diagonal code along a coherent retraction.

    Requires retr(sect a) = a and the coherence law
    ev_dst(u, v) = ev_src(retr u, retr v); then sect(c) is a diagonal code.
    """
    if any(retr(sect(a)) != a for a in codes_src):
        return False
    if any(ev_dst(u, v) != ev_src(retr(u), retr(v))
           for u in codes_dst for v in codes_dst):
        return False
    if not is_diagonal_code(codes_src, ev_src, f, c):
        return False
    return is_diagonal_code(codes_dst, ev_dst, f, sect(c))


def bisimulation_observation(ev_src: Table, ev_dst: Table,
                             pairs: Sequence[Tuple[Hashable, Hashable]],
                             obs: Callable[[Hashable, Hashable], bool]
                             ) -> Tuple[bool, bool]:
    """Return (observationally equal, literally equal) over the related pairs.

    A bisimulation guarantees only the first component.
    """
    obs_ok = all(obs(ev_src(a, a), ev_dst(c, c)) for a, c in pairs)
    lit_ok = all(ev_src(a, a) == ev_dst(c, c) for a, c in pairs)
    return (obs_ok, lit_ok)


if __name__ == "__main__":
    # The pitch-class triad: formal <-> contrapuntal, inversion x -> -x.
    inv: Callable[[Hashable], Hashable] = lambda x: (-int(x)) % 12
    formal: List[Hashable] = ["selfInvert", "selfTritone"] + [("lit", b) for b in range(12)]
    musical: List[Hashable] = ["crab", "crabTritone"] + [("note", b) for b in range(12)]

    def sv_f(x: Hashable) -> int:
        return 0 if x == "selfInvert" else 3 if x == "selfTritone" else int(x[1])

    def sv_m(x: Hashable) -> int:
        return 0 if x == "crab" else 3 if x == "crabTritone" else int(x[1])

    def ev_f(a: Hashable, x: Hashable) -> Hashable:
        if a == "selfInvert":
            return (-sv_f(x)) % 12
        if a == "selfTritone":
            return (6 - sv_f(x)) % 12
        return int(a[1])

    def ev_m(a: Hashable, x: Hashable) -> Hashable:
        if a == "crab":
            return (-sv_m(x)) % 12
        if a == "crabTritone":
            return (6 - sv_m(x)) % 12
        return int(a[1])

    def phi(a: Hashable) -> Hashable:
        return {"selfInvert": "crab", "selfTritone": "crabTritone"}.get(
            a, ("note", a[1]) if isinstance(a, tuple) else a)

    print(transport_diagonal_code(formal, ev_f, musical, ev_m, phi,
                                  inv, "selfInvert"))
